    if(PAINT.editor&&b.editorSnapshot)PAINT.editor.restoreSnapshot(b.editorSnapshot);if(PAINT.editor){PAINT.editor.history=b.editorHistory||[];PAINT.editor.redoStack=b.editorRedo||[];Object.assign(PAINT.editor,b.editorSettings||{});}if(PAINT.setCurrentName)PAINT.setCurrentName(b.currentName||'texture');
