  box?.classList.toggle('is-running',runner.running);box?.classList.toggle('has-failures',!runner.running&&fail>0);if(run)run.disabled=runner.running;if(stop)stop.disabled=!runner.running;
  badge.textContent=runner.running?'RUNNING':runner.results.length?(fail?'FAILED':'PASSED'):'IDLE';
  if(runner.running){status.dataset.kind='running';status.textContent=`Running: ${runner.current||'starting…'} · ${pass} pass · ${fail} fail · ${sk} skip`;}
  else if(runner.results.length){status.dataset.kind=fail?'error':sk?'warn':'ok';status.textContent=`Finished · ${pass} passed · ${fail} failed · ${sk} skipped · ${Math.round((runner.finishedAt||performance.now())-runner.startedAt)} ms`;}
