  pre.textContent=runner.results.length?runner.results.map(r=>`[${r.status}] ${String(r.ms).padStart(5,' ')} ms  ${r.name}${r.message?` — ${r.message}`:''}`).join('\n'):'No automatic test has run yet.';pre.scrollTop=pre.scrollHeight;
