async function waitFor(fn,{timeout=6000,interval=40,message='Condition timed out'}={}){const start=performance.now();while(performance.now()-start<timeout){if(runner.cancelled)throw new Cancelled();try{if(await fn())return true;}catch(_){}await sleep(interval);}throw new Error(message);}
