function parseModelBytes(name,data){const raw=data instanceof Uint8Array?data:new Uint8Array(data);const ab=raw.buffer.slice(raw.byteOffset,raw.byteOffset+raw.byteLength);return /\.mdl$/i.test(name)?CORE.parseMDL(new TextDecoder().decode(raw),name):CORE.parseMDX(ab,name);}
function featureCapabilities(m){return{geosets:(m.geosets||[]).length,textures:(m.textureDefs||m.textures||[]).length,materials:(m.materials||[]).length,sequences:(m.sequences||[]).length,nodes:(m.nodes||[]).length,bones:(m.bones||[]).length,helpers:(m.helpers||[]).length,cameras:(m.cameras||[]).length,particleEmitters2:(m.particleEmitters2||[]).length,skin4:(m.geosets||[]).filter(g=>g?.skin?.length>=8).length,unknownChunks:(m.unknownChunks||[]).length};}
